queries.aggregate:
WITH line_totals AS (
  SELECT order_id, SUM(amount) AS total FROM lines GROUP BY order_id
), payment_totals AS (
  SELECT order_id, SUM(amount) AS total FROM payments GROUP BY order_id
)
SELECT o.id AS order_id, COALESCE(l.total, 0) AS line_total, COALESCE(p.total, 0) AS payment_total
FROM orders o LEFT JOIN line_totals l ON l.order_id = o.id
LEFT JOIN payment_totals p ON p.order_id = o.id
ORDER BY o.id;
